import{_ as e,c as a,o as t,a2 as o}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"Update Commands","description":"","frontmatter":{"sidebarPos":15,"sidebarTitle":"Overview","sidebarGroupTitle":"Update"},"headers":[],"relativePath":"guide/console/update/overview.md","filePath":"guide/console/update/overview.md","lastUpdated":1778363927000}'),d={name:"guide/console/update/overview.md"},n=o('<h1 id="update-commands" tabindex="-1">Update Commands <a class="header-anchor" href="#update-commands" aria-label="Permalink to &quot;Update Commands&quot;">​</a></h1><p>Update commands patch host-application configuration files to align with Modularous requirements during installation or version upgrades. They perform <strong>surgical, reversible edits</strong> to keep your <code>config/*.php</code> files compatible — they don&#39;t overwrite your customisations.</p><div class="warning custom-block"><p class="custom-block-title">Internal commands</p><p>All Update commands have <code>$hidden = true</code> and are not listed in <code>php artisan list</code>. They are invoked automatically by <code>modularous:install</code> and by the upgrade guide, but you can run them manually when something drifts.</p></div><table><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/guide/console/update/update-laravel-configs">modularous:update:laravel:configs</a></td><td>Patch <code>config/auth.php</code> and optional config files for Modularous guards</td></tr></tbody></table><h2 id="when-to-run-these-manually" tabindex="-1">When to Run These Manually <a class="header-anchor" href="#when-to-run-these-manually" aria-label="Permalink to &quot;When to Run These Manually&quot;">​</a></h2><table><thead><tr><th>Symptom</th><th>Likely fix</th></tr></thead><tbody><tr><td>Login page rejects valid credentials with &quot;guard not defined&quot;</td><td><code>php artisan modularous:update:laravel:configs</code></td></tr><tr><td>Fresh clone missing Modularous guards in <code>config/auth.php</code></td><td><code>php artisan modularous:update:laravel:configs</code></td></tr><tr><td>Upgraded Modularous and release notes mention new guards / providers</td><td><code>php artisan modularous:update:laravel:configs</code></td></tr></tbody></table><p>Always diff <code>config/auth.php</code> against git before committing after running an Update command — the patch is transparent, but you should understand what changed.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/get-started/upgrading">Upgrading</a> — the primary context for Update commands</li><li><a href="./../setup/install">Setup / install</a> — invokes Update commands automatically on first install</li></ul>',9),r=[n];function i(s,l,c,u,p,h){return t(),a("div",null,r)}const f=e(d,[["render",i]]);export{g as __pageData,f as default};
